import React from 'react';

export function OrbMain() {
  return (
    <>
      {/* outer glow */}
      <div style={{
        position: 'absolute', left: '50%', transform: 'translateX(-50%)',
        width: 360, height: 360, top: 100,
        borderRadius: '50%', pointerEvents: 'none',
        background: 'radial-gradient(circle at 40% 40%, rgba(126,200,200,0.35) 0%, rgba(45,107,107,0.12) 55%, transparent 75%)',
        filter: 'blur(32px)',
        animation: 'orbFloat 10s ease-in-out infinite reverse',
      }} />
      {/* main orb */}
      <div style={{
        position: 'absolute', left: '50%', transform: 'translateX(-50%)',
        width: 240, height: 240, top: 130,
        borderRadius: '50%', pointerEvents: 'none',
        background: 'radial-gradient(circle at 38% 35%, #7EC8C8 0%, #2D6B6B 45%, #1A3A3A 100%)',
        boxShadow: '0 0 100px rgba(45,107,107,0.4), 0 0 40px rgba(126,200,200,0.15)',
        animation: 'orbFloat 8s ease-in-out infinite',
      }} />
    </>
  );
}

export function OrbSmall({ style = {} }) {
  return (
    <div style={{
      width: 72, height: 72, borderRadius: '50%', flexShrink: 0,
      background: 'radial-gradient(circle at 38% 35%, #7EC8C8, #2D6B6B)',
      boxShadow: '0 0 40px rgba(45,107,107,0.35)',
      animation: 'orbFloatFree 6s ease-in-out infinite',
      ...style,
    }} />
  );
}

// Identical to OrbMain but positioned in flow (not absolute)
// animKey forces remount so CSS animation restarts on phase change
export function OrbBreathing({ animKey, phase, running }) {
  // Inject keyframes once
  if (typeof document !== 'undefined' && !document.getElementById('orb-breath-kf')) {
    const s = document.createElement('style');
    s.id = 'orb-breath-kf';
    s.textContent = `
      @keyframes orbIdle {
        0%,100% { transform: scale(1); }
        50%      { transform: scale(1.06); }
      }
      @keyframes orbIn  {
        from { transform: scale(1);    }
        to   { transform: scale(1.42); }
      }
      @keyframes orbHold {
        from { transform: scale(1.42); }
        to   { transform: scale(1.42); }
      }
      @keyframes orbOut {
        from { transform: scale(1.42); }
        to   { transform: scale(0.88); }
      }
    `;
    document.head.appendChild(s);
  }

  const ANIMS = [
    `orbIn   4s cubic-bezier(0.4,0,0.2,1) forwards`,
    `orbHold 7s linear                    forwards`,
    `orbOut  8s cubic-bezier(0.4,0,0.2,1) forwards`,
  ];

  const anim = !running
    ? 'orbIdle 6s ease-in-out infinite'
    : ANIMS[phase];

  return (
    <div style={{ position: 'relative', width: 240, height: 240, flexShrink: 0 }}>
      {/* outer glow — same as OrbMain */}
      <div style={{
        position: 'absolute',
        width: 360, height: 360,
        top: '50%', left: '50%',
        transform: 'translate(-50%, -50%)',
        borderRadius: '50%', pointerEvents: 'none',
        background: 'radial-gradient(circle at 40% 40%, rgba(126,200,200,0.35) 0%, rgba(45,107,107,0.12) 55%, transparent 75%)',
        filter: 'blur(32px)',
      }} />
      {/* main orb — animates */}
      <div
        key={animKey}
        style={{
          width: 240, height: 240,
          borderRadius: '50%',
          background: 'radial-gradient(circle at 38% 35%, #7EC8C8 0%, #2D6B6B 45%, #1A3A3A 100%)',
          boxShadow: '0 0 100px rgba(45,107,107,0.4), 0 0 40px rgba(126,200,200,0.15)',
          animation: anim,
          transformOrigin: 'center center',
          position: 'relative', zIndex: 1,
          display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column',
        }}
      />
    </div>
  );
}
